window.__votdWeek && window.__votdWeek({"week":"2029-01-29","reading":"Doctrine and Covenants 3–5","days":[{"d":"2029-01-29","ref":"D&C 3:2","b":"D&C","c":3,"v":2,"he":"כִּי אֵל לֹא יֵלֵךְ בׇּאֳרָחוֹת עֲקַלְקַלּוֹת וְלֹא יָסוּר יָמִין וּשְׂמֹאל וְלֹא יִשְׁתַּנֶּה מֵאֲשֶׁר דִּבֵּר עַל־כֵּן אֹרְחֹתָיו יְשָׁרִים וְדַרְכּוֹ מַעְגַּל עוֹלָם׃","en":"For God doth not walk in crooked paths, neither doth he turn to the right hand nor to the left, neither doth he vary from that which he hath said, therefore his paths are straight, and his course is one eternal round."},{"d":"2029-01-30","ref":"D&C 3:7","b":"D&C","c":3,"v":7,"he":"כִּי הִנֵּה לֹא הָיָה לְךָ לִירֹא אָדָם יוֹתֵר מֵאֱלֹהִים גַּם־כִּי יָפֵרוּ אֲנָשִׁים אֶת־עֲצוֹת אֱלֹהִים וְיִבְזוּ דְבָרָיו׃","en":"For, behold, you should not have feared man more than God. Although men set at naught the counsels of God, and despise his words—"},{"d":"2029-01-31","ref":"D&C 3:8","b":"D&C","c":3,"v":8,"he":"אֲבָל אַתָּה הָיָה לְךָ לִהְיוֹת נֶאֱמָן וְהוּא נָטָה זְרוֹעוֹ וְהָיָה לְךָ לְמִשְׁעָן מִפְּנֵי כׇּל־חִצֵּי הַשָּׂטָן הַבּוֹעֲרִים וְהָיָה עִמְּךָ בְּכׇל־עֵת צָרָה׃","en":"Yet you should have been faithful; and he would have extended his arm and supported you against all the fiery darts of the adversary; and he would have been with you in every time of trouble."},{"d":"2029-02-01","ref":"D&C 4:2","b":"D&C","c":4,"v":2,"he":"עַל־כֵּן כׇּל־הַבָּאִים לַעֲבֹדַת אֱלֹהִים רְאוּ כִּי תַּעַבְדוּ אֹתוֹ בְּכׇל־לְבַבְכֶם וּבְכׇל־מְאֹדְכֶם וּבְכׇל־מַדַּעֲכֶם וּבְכׇל־כֹּחֲכֶם לְמַעַן תַּעַמְדוּ נְקִיִּים לִפְנֵי אֱלֹהִים בַּיּוֹם הָאַחֲרוֹן׃","en":"Therefore, O ye that embark in the service of God, see that ye serve him with all your heart, might, mind and strength, that ye may stand blameless before God at the last day."},{"d":"2029-02-02","ref":"D&C 4:4","b":"D&C","c":4,"v":4,"he":"כִּי הִנֵּה הַשָּׂדֶה כְּבָר הִלְבִּין לַקָּצִיר וְהִנֵּה הַשֹּׁלֵחַ מַגָּלוֹ בְּכׇל־כֹּחוֹ הוּא יֶאֱסֹף לוֹ אוֹצָר וְלֹא יֹאבַד אַךְ יָבִיא תְשׁוּעָה לְנַפְשׁוֹ׃","en":"For behold the field is white already to harvest; and lo, he that thrusteth in his sickle with his might, the same layeth up in store that he perisheth not, but bringeth salvation to his soul;"},{"d":"2029-02-03","ref":"D&C 4:5","b":"D&C","c":4,"v":5,"he":"וֶאֱמוּנָה וְתִקְוָה וְחֶסֶד וְאַהֲבָה וְעַיִן תְּמִימָה לִכְבוֹד אֱלֹהִים יְכִינוּ אֹתוֹ לַמְּלָאכָה׃","en":"And faith, hope, charity and love, with an eye single to the glory of God, qualify him for the work."},{"d":"2029-02-04","ref":"D&C 5:33","b":"D&C","c":5,"v":33,"he":"וְרַבִּים אֹרְבִים לְהַשְׁמִידְךָ מֵעַל פְּנֵי הָאֲדָמָה וּלְמַעַן יַאֲרִיכוּ יָמֶיךָ נָתַתִּי לְךָ אֶת־הַמִּצְוֹת הָאֵלֶּה׃","en":"And there are many that lie in wait to destroy thee from off the face of the earth; and for this cause, that thy days may be prolonged, I have given unto thee these commandments."}]});
